      "batch.banner.compliant-confirm": { en: "Install these compliant builds: {list}?", zh: "\u786E\u8BA4\u5B89\u88C5\u4EE5\u4E0B\u5408\u89C4\u7248\uFF1A{list}\uFF1F", draft: true },
